import math

def std_dev(r_idx, c_idx):
    region_rows = regions[f'r{r_idx}']
    region_cols = regions[f'c{c_idx}']

    vals = []
    for r_cell in region_rows:
        for c_cell in region_cols:
            vals.append(demo_in[r_cell][c_cell])

    mean = sum(vals) / len(vals)
    variance = sum((x - mean)**2 for x in vals) / len(vals)
    return math.sqrt(variance)

print("\nStandard deviation:")
for r in range(3):
    row = []
    for c in range(3):
        row.append(round(std_dev(r, c), 2))
    print(row)

def entropy(r_idx, c_idx):
    region_rows = regions[f'r{r_idx}']
    region_cols = regions[f'c{c_idx}']

    from collections import Counter
    vals = [demo_in[r_cell][c_cell] for r_cell in region_rows for c_cell in region_cols]
    counts = Counter(vals)
    total = sum(counts.values())

    ent = 0
    for count in counts.values():
        p = count / total
        if p > 0:
            ent -= p * math.log2(p)
    return round(ent, 2)

print("\nEntropy:")
for r in range(3):
    row = []
    for c in range(3):
        row.append(entropy(r, c))
    print(row)

